package com.opencheps;
import com.opencheps.camera.CameraOpening;import com.opencheps.engine.PositionHistory;import com.opencheps.util.Side;import com.opencheps.vision.*;import org.junit.Test;import static org.junit.Assert.*;
public class CameraOpeningTest {
    private float[][] costs(ChessPosition position){float[][] c=new float[64][13];for(int i=0;i<64;i++){java.util.Arrays.fill(c[i],.6f);c[i][VisualMoveTracker.PIECES.indexOf(position.board[i/8][i%8])]=.005f;}return c;}
    @Test public void everyObservedFirstWhiteMoveGivesBlackTheTurn(){for(ChessPosition next:CameraOpening.initial().successors()){VisualMoveTracker.Match m=VisualMoveTracker.match(CameraOpening.initial(),costs(next));assertNotNull(m);assertEquals(next.move,m.position.move);assertEquals(1,m.plies);assertEquals(Side.BLACK,m.position.turn);}}
    @Test public void confirmedFirstMoveAndBlackReplyAreRecordedInOrder(){for(ChessPosition next:CameraOpening.initial().successors()){PositionHistory h=new PositionHistory();h.reset(FenBuilder.build(CameraOpening.initial().board,Side.WHITE,Side.WHITE,"KQkq","-",0,1));h.advance(next);assertEquals(1,h.snapshot().plies);ChessPosition reply=next.successors().get(0);h.advance(reply);assertEquals(2,h.snapshot().plies);assertEquals(2,h.snapshot().fullmove);assertTrue(h.snapshot().command.endsWith(" moves "+next.move+" "+reply.move));}}
    @Test public void autoOpeningRecognizesAllTwentyFirstMoves(){for(ChessPosition next:CameraOpening.initial().successors()){VisualMoveTracker.Match m=VisualMoveTracker.matchOpening(CameraOpening.initial(),costs(next));assertNotNull(next.move,m);assertEquals(1,m.plies);assertEquals(next.move,m.position.move);assertEquals(Side.BLACK,m.position.turn);}}
    @Test public void autoOpeningDoesNotInventBlackReply(){ChessPosition first=CameraOpening.initial().successors().get(0),reply=first.successors().get(0);assertNull(VisualMoveTracker.matchOpening(CameraOpening.initial(),costs(reply)));}
    @Test public void autoOpeningRejectsAmbiguousAndCoveredDiagram(){float[][] c=costs(CameraOpening.initial());for(float[] row:c)java.util.Arrays.fill(row,.2f);assertNull(VisualMoveTracker.matchOpening(CameraOpening.initial(),c));}
    @Test public void autoOpeningRejectsAdvancedMidgame(){PositionSeed p=PositionSeed.parse("r1bqkb1r/ppp2ppp/3p1n2/4p3/2BnP3/2N2N2/PPPP1PPP/R1BQ1RK1 b kq - 0 6",Side.BLACK);assertNotNull(p);assertNull(VisualMoveTracker.matchOpening(CameraOpening.initial(),costs(p.position)));}
    @Test public void autoOpeningToleratesCameraResidualOnlyWithWholeBoardAgreement(){ChessPosition first=CameraOpening.initial().successors().get(0);float[][] c=costs(first);for(int i=0;i<64;i++)c[i][VisualMoveTracker.PIECES.indexOf(first.board[i/8][i%8])]=.09f;assertNull(VisualMoveTracker.match(CameraOpening.initial(),c));assertNotNull(VisualMoveTracker.matchOpening(CameraOpening.initial(),c));}
}
